export interface NavItem {
  label: string;
  path: string;
  icon: string;
}

export enum AspectRatio {
  SQUARE = "1:1",
  PORTRAIT_2_3 = "2:3",
  LANDSCAPE_3_2 = "3:2",
  PORTRAIT_3_4 = "3:4",
  LANDSCAPE_4_3 = "4:3",
  PORTRAIT_9_16 = "9:16",
  LANDSCAPE_16_9 = "16:9",
  CINEMATIC_21_9 = "21:9"
}

export enum ImageSize {
  SIZE_1K = "1K",
  SIZE_2K = "2K",
  SIZE_4K = "4K"
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  isThinking?: boolean;
}

import { GoogleGenAI, GenerateContentResponse, Modality, LiveServerMessage } from "@google/genai";
import { AspectRatio, ImageSize } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// --- Image Generation & Editing ---

export const generateImage = async (
  prompt: string,
  aspectRatio: AspectRatio,
  size: ImageSize
): Promise<string | null> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: {
        parts: [{ text: prompt }],
      },
      config: {
        imageConfig: {
          aspectRatio: aspectRatio,
          imageSize: size,
        },
      },
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    return null;
  } catch (error) {
    console.error("Image generation error:", error);
    throw error;
  }
};

export const editImage = async (
  base64Image: string,
  prompt: string,
  mimeType: string = "image/png"
): Promise<string | null> => {
  try {
    const cleanBase64 = base64Image.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              data: cleanBase64,
              mimeType: mimeType,
            },
          },
          { text: prompt },
        ],
      },
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    return null;
  } catch (error) {
    console.error("Image editing error:", error);
    throw error;
  }
};

// --- Text Chat (Fast & Thinking) ---

export const chatFast = async (message: string): Promise<string> => {
  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: 'gemini-flash-lite-latest',
      contents: message,
    });
    return response.text || "No response generated.";
  } catch (error) {
    console.error("Fast chat error:", error);
    return "System Error: Neural link unstable.";
  }
};

export const chatThinking = async (message: string): Promise<string> => {
  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: message,
      config: {
        thinkingConfig: { thinkingBudget: 32768 },
      },
    });
    return response.text || "No thoughts detected.";
  } catch (error) {
    console.error("Thinking chat error:", error);
    return "System Error: Deep processing failed.";
  }
};

// --- Live Audio API Helpers ---

// Helper to encode PCM data to base64
export function encodePCM(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

// Helper to decode base64 to PCM Float32
export function decodePCM(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number = 24000,
  numChannels: number = 1,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export const connectLiveSession = async (
  onAudioData: (base64Audio: string) => void,
  onClose: () => void
): Promise<{ 
    sendAudio: (pcmData: Float32Array) => void; 
    close: () => void;
}> => {

  const sessionPromise = ai.live.connect({
    model: 'gemini-2.5-flash-native-audio-preview-09-2025',
    config: {
      responseModalities: [Modality.AUDIO],
      systemInstruction: "You are KNON, a highly advanced, slightly cryptic, neo-noir AI assistant. You speak efficiently and intelligently about visual arts, technology, and the digital frontier.",
    },
    callbacks: {
        onopen: () => console.log('Live session connected'),
        onmessage: (msg: LiveServerMessage) => {
            const audioData = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (audioData) {
                onAudioData(audioData);
            }
        },
        onclose: () => {
            console.log('Live session closed');
            onClose();
        },
        onerror: (err) => console.error('Live session error', err)
    }
  });

  const sendAudio = (float32Data: Float32Array) => {
    // Convert Float32 to Int16 for Gemini
    const int16 = new Int16Array(float32Data.length);
    for (let i = 0; i < float32Data.length; i++) {
      int16[i] = Math.max(-1, Math.min(1, float32Data[i])) * 0x7FFF;
    }

    const base64Data = encodePCM(new Uint8Array(int16.buffer));

    sessionPromise.then(session => {
        session.sendRealtimeInput({
            media: {
                mimeType: 'audio/pcm;rate=16000',
                data: base64Data
            }
        });
    });
  };

  const close = () => {
    sessionPromise.then(s => s.close());
  };

  return { sendAudio, close };
};

