import React, { useState, useRef } from 'react';
import { generateImage, editImage } from '../services/geminiService';
import { AspectRatio, ImageSize } from '../types';

type Mode = 'GENERATE' | 'EDIT';

const EditLab: React.FC = () => {
  const [mode, setMode] = useState<Mode>('GENERATE');
  const [prompt, setPrompt] = useState('');
  const [loading, setLoading] = useState(false);
  const [resultImage, setResultImage] = useState<string | null>(null);

  // Gen specific
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>(AspectRatio.SQUARE);
  const [imageSize, setImageSize] = useState<ImageSize>(ImageSize.SIZE_1K);

  // Edit specific
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleExecute = async () => {
    if (!prompt) return;
    setLoading(true);
    setResultImage(null);

    try {
      if (mode === 'GENERATE') {
        const result = await generateImage(prompt, aspectRatio, imageSize);
        setResultImage(result);
      } else {
        if (!selectedImage) return;
        const result = await editImage(selectedImage, prompt);
        setResultImage(result);
      }
    } catch (e) {
      console.error(e);
      alert("Operation failed. Check console.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen pt-20 pb-32 px-6 flex flex-col items-center max-w-7xl mx-auto">
      <div className="w-full mb-10 border-b border-white/10 pb-6 flex justify-between items-end">
        <div>
           <h1 className="text-5xl font-black uppercase mb-2">Visual Lab</h1>
           <p className="text-white/50 font-mono text-sm">Gemini 2.5 Flash Image & 3.0 Pro Image Preview</p>
        </div>
        <div className="flex gap-2">
            <button 
                onClick={() => setMode('GENERATE')}
                className={`px-6 py-2 rounded border transition-all ${mode === 'GENERATE' ? 'bg-primary text-black border-primary font-bold' : 'border-white/20 text-white/60 hover:text-white'}`}
            >
                GENERATE
            </button>
            <button 
                onClick={() => setMode('EDIT')}
                className={`px-6 py-2 rounded border transition-all ${mode === 'EDIT' ? 'bg-secondary text-black border-secondary font-bold' : 'border-white/20 text-white/60 hover:text-white'}`}
            >
                EDIT
            </button>
        </div>
      </div>

      <div className="flex flex-col lg:flex-row gap-12 w-full">
        {/* Controls */}
        <div className="w-full lg:w-1/3 flex flex-col gap-8">

            {mode === 'GENERATE' ? (
                <div className="space-y-6 animate-pulse-slow bg-surface p-6 rounded border border-white/5">
                    <div>
                        <label className="block text-xs font-bold text-primary mb-2 tracking-widest">ASPECT RATIO</label>
                        <div className="grid grid-cols-4 gap-2">
                            {Object.values(AspectRatio).map((ratio) => (
                                <button 
                                    key={ratio}
                                    onClick={() => setAspectRatio(ratio)}
                                    className={`text-xs py-2 border rounded transition-colors ${aspectRatio === ratio ? 'border-primary text-primary bg-primary/10' : 'border-white/10 text-white/40 hover:border-white/30'}`}
                                >
                                    {ratio}
                                </button>
                            ))}
                        </div>
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-primary mb-2 tracking-widest">RESOLUTION</label>
                        <div className="grid grid-cols-3 gap-2">
                            {Object.values(ImageSize).map((size) => (
                                <button 
                                    key={size}
                                    onClick={() => setImageSize(size)}
                                    className={`text-xs py-2 border rounded transition-colors ${imageSize === size ? 'border-primary text-primary bg-primary/10' : 'border-white/10 text-white/40 hover:border-white/30'}`}
                                >
                                    {size}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            ) : (
                <div className="space-y-6 bg-surface p-6 rounded border border-white/5">
                    <label className="block text-xs font-bold text-secondary mb-2 tracking-widest">SOURCE IMAGE</label>
                    <div 
                        onClick={() => fileInputRef.current?.click()}
                        className="w-full aspect-video border-2 border-dashed border-white/20 rounded hover:border-secondary hover:bg-secondary/5 cursor-pointer flex items-center justify-center relative overflow-hidden transition-all"
                    >
                        {selectedImage ? (
