             ) : (
                 <div className="text-white/20 flex flex-col items-center">
                     <span className="material-symbols-outlined text-6xl mb-4">image</span>
                     <p className="font-mono text-sm tracking-widest">AWAITING OUTPUT SIGNAL</p>
                 </div>
             )}
        </div>
      </div>
    </div>
  );
};

export default EditLab;

import React, { useState, useEffect, useRef } from 'react';
import { chatFast, chatThinking } from '../services/geminiService';
import { ChatMessage } from '../types';

const Chat: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: "Systems online. Connected to KNON network. Select mode: FAST (Flash-Lite) or DEEP (Pro Thinking). How may I assist?" }
  ]);
  const [input, setInput] = useState('');
  const [isThinkingMode, setIsThinkingMode] = useState(false);
  const [loading, setLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(scrollToBottom, [messages]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMsg: ChatMessage = { role: 'user', text: input };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setLoading(true);

    try {
      const responseText = isThinkingMode 
        ? await chatThinking(input)
        : await chatFast(input);

      const modelMsg: ChatMessage = { 
          role: 'model', 
          text: responseText, 
          isThinking: isThinkingMode 
      };
      setMessages(prev => [...prev, modelMsg]);
    } catch (e) {
      setMessages(prev => [...prev, { role: 'model', text: "Error: Connection interrupted." }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen pt-20 pb-32 px-4 md:px-0 max-w-4xl mx-auto flex flex-col">
      <div className="flex-1 bg-surface border border-white/10 rounded-lg overflow-hidden flex flex-col h-[70vh]">

        {/* Header */}
        <div className="bg-background-dark p-4 border-b border-white/10 flex justify-between items-center">
            <div className="flex items-center gap-2">
                <span className="material-symbols-outlined text-primary">chat</span>
                <span className="font-bold tracking-widest">INTEL_TERMINAL</span>
            </div>
            <div className="flex bg-white/5 rounded p-1 gap-1">
                <button 
                    onClick={() => setIsThinkingMode(false)}
                    className={`px-3 py-1 text-xs font-bold rounded transition-colors ${!isThinkingMode ? 'bg-primary text-black' : 'text-white/50 hover:text-white'}`}
                >
                    FAST
                </button>
                <button 
                    onClick={() => setIsThinkingMode(true)}
                    className={`px-3 py-1 text-xs font-bold rounded transition-colors ${isThinkingMode ? 'bg-secondary text-black' : 'text-white/50 hover:text-white'}`}
                >
                    DEEP THINK
                </button>
            </div>
        </div>

        {/* Messages */}
        <div className="flex-1 overflow-y-auto p-6 space-y-6">
            {messages.map((msg, idx) => (
                <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                    <div className={`max-w-[80%] p-4 rounded-lg font-mono text-sm leading-relaxed ${
                        msg.role === 'user' 
                            ? 'bg-white/10 border border-white/20 text-white' 
                            : isThinkingMode && msg.isThinking
                                ? 'bg-secondary/10 border border-secondary/30 text-secondary-100'
                                : 'bg-primary/5 border border-primary/20 text-primary-100'
                    }`}>
                        {msg.role === 'model' && msg.isThinking && (
                             <div className="text-[10px] uppercase tracking-widest opacity-50 mb-2 pb-2 border-b border-secondary/20 flex items-center gap-2">
                                <span className="material-symbols-outlined text-sm">psychology</span>
                                Gemini 3.0 Thinking
                             </div>
                        )}
                        {msg.text}
                    </div>
                </div>
            ))}
            {loading && (
                <div className="flex justify-start">
                    <div className="bg-white/5 p-4 rounded-lg flex gap-2">
                        <span className="w-2 h-2 bg-white/50 rounded-full animate-bounce"></span>
                        <span className="w-2 h-2 bg-white/50 rounded-full animate-bounce delay-100"></span>
                        <span className="w-2 h-2 bg-white/50 rounded-full animate-bounce delay-200"></span>
                    </div>
                </div>
            )}
            <div ref={messagesEndRef} />
        </div>

        {/* Input */}
        <div className="p-4 bg-background-dark border-t border-white/10">
            <div className="flex gap-4">
                <input 
                    type="text" 
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                    placeholder="Enter command or query..."
                    className="flex-1 bg-surface border border-white/10 rounded px-4 py-3 text-white focus:border-primary outline-none font-mono"
                />
                <button 
                    onClick={handleSend}
                    disabled={loading}
                    className="bg-primary hover:bg-white text-black font-bold px-6 rounded transition-colors disabled:opacity-50"
                >
                    SEND
                </button>
            </div>
        </div>
      </div>
    </div>
  );
};

export default Chat;

import React, { useEffect, useRef, useState } from 'react';
import { connectLiveSession, decodeAudioData } from '../services/geminiService';

const LiveSession: React.FC = () => {
    const [connected, setConnected] = useState(false);
    const [active, setActive] = useState(false);
    const [status, setStatus] = useState("DISCONNECTED");

    // Audio Context Refs
    const inputAudioContextRef = useRef<AudioContext | null>(null);
    const outputAudioContextRef = useRef<AudioContext | null>(null);
    const sessionControlRef = useRef<{ sendAudio: (data: Float32Array) => void; close: () => void } | null>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const processorRef = useRef<ScriptProcessorNode | null>(null);
    const sourceRef = useRef<MediaStreamAudioSourceNode | null>(null);

    // Playback Queue
    const nextStartTimeRef = useRef<number>(0);
    const audioQueueRef = useRef<AudioBuffer[]>([]);

    const canvasRef = useRef<HTMLCanvasElement>(null);

    const initAudio = async () => {
        try {
            setStatus("INITIALIZING AUDIO...");
            const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
            const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

            inputAudioContextRef.current = inputCtx;
            outputAudioContextRef.current = outputCtx;

            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            streamRef.current = stream;

            // Connect to Gemini
            setStatus("ESTABLISHING UPLINK...");
            const session = await connectLiveSession(
                async (base64Audio) => {
                    // Handle incoming audio
                    if (!outputCtx) return;

                    // Decode
                    const audioBuffer = await decodeAudioData(
                        Uint8Array.from(atob(base64Audio), c => c.charCodeAt(0)),
                        outputCtx
                    );

                    // Schedule Playback
                    const source = outputCtx.createBufferSource();
                    source.buffer = audioBuffer;
                    source.connect(outputCtx.destination);

                    const currentTime = outputCtx.currentTime;
                    if (nextStartTimeRef.current < currentTime) {
                        nextStartTimeRef.current = currentTime;
                    }

                    source.start(nextStartTimeRef.current);
                    nextStartTimeRef.current += audioBuffer.duration;
                },
                () => {
                    handleDisconnect();
                }
            );

            sessionControlRef.current = session;

            // Setup Input Processing
            const source = inputCtx.createMediaStreamSource(stream);
            const processor = inputCtx.createScriptProcessor(4096, 1, 1);

            processor.onaudioprocess = (e) => {
                const inputData = e.inputBuffer.getChannelData(0);
                // Send raw float32 data
                session.sendAudio(inputData);
                drawVisualizer(inputData);
            };

            source.connect(processor);
            processor.connect(inputCtx.destination); // Required for script processor to run

            sourceRef.current = source;
            processorRef.current = processor;

            setConnected(true);
            setActive(true);
            setStatus("LIVE UPLINK ESTABLISHED");

        } catch (err) {
            console.error("Audio init error", err);
            setStatus("CONNECTION FAILED");
            handleDisconnect();
        }
    };

    const handleDisconnect = () => {
        sessionControlRef.current?.close();
        streamRef.current?.getTracks().forEach(t => t.stop());
        inputAudioContextRef.current?.close();
        outputAudioContextRef.current?.close();
        processorRef.current?.disconnect();
        sourceRef.current?.disconnect();

        setConnected(false);
        setActive(false);
        setStatus("DISCONNECTED");
        nextStartTimeRef.current = 0;
    };

    const drawVisualizer = (data: Float32Array) => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        ctx.fillStyle = '#050505'; // Background match
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        ctx.lineWidth = 2;
        ctx.strokeStyle = '#06e8f9';
        ctx.beginPath();

        const sliceWidth = canvas.width / data.length;
        let x = 0;

        for (let i = 0; i < data.length; i+=16) { // Downsample for vis
            const v = data[i] * 50; // Amplitude scaling
            const y = (canvas.height / 2) + v;

            if (i === 0) {
                ctx.moveTo(x, y);
            } else {
                ctx.lineTo(x, y);
            }
            x += sliceWidth * 16;
        }

        ctx.lineTo(canvas.width, canvas.height / 2);
        ctx.stroke();
    };

    return (
        <div className="min-h-screen flex items-center justify-center relative overflow-hidden">
            {/* Background Viz */}
            <div className="absolute inset-0 pointer-events-none opacity-20 flex items-center justify-center">
                 <div className={`w-[600px] h-[600px] border border-primary/20 rounded-full flex items-center justify-center transition-all duration-1000 ${active ? 'scale-110 animate-pulse-slow' : 'scale-100'}`}>
                    <div className={`w-[400px] h-[400px] border border-secondary/20 rounded-full flex items-center justify-center transition-all duration-1000 delay-100 ${active ? 'scale-110 animate-pulse' : 'scale-100'}`}>
                        <div className="w-[200px] h-[200px] bg-white/5 rounded-full blur-3xl"></div>
                    </div>
                 </div>
            </div>

            <div className="relative z-10 flex flex-col items-center gap-12 w-full max-w-2xl px-6">
                <div className="text-center">
                    <h1 className="text-4xl font-black uppercase tracking-widest mb-2 glitch-hover">Voice Uplink</h1>
                    <p className="text-primary font-mono text-sm tracking-[0.2em]">{status}</p>
                </div>

                <div className="w-full h-32 bg-surface/50 border border-white/10 rounded-lg overflow-hidden backdrop-blur-md relative">
                     <canvas ref={canvasRef} width={600} height={128} className="w-full h-full" />
                     {!active && (
                         <div className="absolute inset-0 flex items-center justify-center text-white/20 font-mono text-xs">
                             VISUALIZER OFFLINE
                         </div>
                     )}
                </div>

                <button 
                    onClick={connected ? handleDisconnect : initAudio}
                    className={`w-32 h-32 rounded-full border-2 flex items-center justify-center transition-all duration-300 group ${
                        connected 
                        ? 'border-red-500 hover:bg-red-500/10 text-red-500 shadow-[0_0_30px_rgba(239,68,68,0.3)]' 
                        : 'border-primary hover:bg-primary/10 text-primary shadow-[0_0_30px_rgba(6,232,249,0.3)] hover:scale-110'
                    }`}
                >
                    <span className="material-symbols-outlined text-5xl">
                        {connected ? 'call_end' : 'mic'}
                    </span>
                </button>

                <p className="text-white/40 text-xs font-mono max-w-md text-center leading-relaxed">
                    Powered by Gemini 2.5 Native Audio. Establish a real-time, low-latency voice connection with the KNON AI core. Speak freely.
                </p>
            </div>
        </div>
    );
};

