  }
};

export const chatThinking = async (message: string): Promise<string> => {
  try {
    const ai = getAI();
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: message,
      config: {
        thinkingConfig: { thinkingBudget: 32768 },
      },
    });
    return response.text || "No thoughts detected.";
  } catch (error) {
