    return "System Error: Deep processing failed.";
  }
};

export const chatWithSearch = async (message: string): Promise<{text: string, sources: Array<{title: string, uri: string}>}> => {
    try {
        const ai = getAI();
        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview", // Flash is good for search
            contents: message,
            config: {
                tools: [{googleSearch: {}}],
            },
        });

        const text = response.text || "No data found.";
        const sources: Array<{title: string, uri: string}> = [];

        const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
        chunks.forEach((chunk: any) => {
            if (chunk.web?.uri) {
                sources.push({
                    title: chunk.web.title || "Source",
                    uri: chunk.web.uri
                });
            }
        });

        return { text, sources };
    } catch (error) {
        console.error("Search chat error:", error);
        return { text: "Search Uplink Failed.", sources: [] };
    }
}

// --- Live Audio API Helpers ---

// Helper to encode PCM data to base64
export function encodePCM(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

// Helper to decode base64 to PCM Float32
export function decodePCM(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number = 24000,
  numChannels: number = 1,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export const connectLiveSession = async (
  onAudioData: (base64Audio: string) => void,
  onClose: () => void
): Promise<{ 
    sendAudio: (pcmData: Float32Array) => void; 
    close: () => void;
}> => {

  const ai = getAI();
  const sessionPromise = ai.live.connect({
    model: 'gemini-2.5-flash-native-audio-preview-09-2025',
    config: {
      responseModalities: [Modality.AUDIO],
      systemInstruction: "You are KNON, a highly advanced, slightly cryptic, neo-noir AI assistant. You speak efficiently and intelligently about visual arts, technology, and the digital frontier.",
    },
    callbacks: {
        onopen: () => console.log('Live session connected'),
        onmessage: (msg: LiveServerMessage) => {
            const audioData = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (audioData) {
                onAudioData(audioData);
            }
        },
        onclose: () => {
            console.log('Live session closed');
            onClose();
        },
        onerror: (err) => console.error('Live session error', err)
    }
  });

  const sendAudio = (float32Data: Float32Array) => {
    // Convert Float32 to Int16 for Gemini
    const int16 = new Int16Array(float32Data.length);
    for (let i = 0; i < float32Data.length; i++) {
      int16[i] = Math.max(-1, Math.min(1, float32Data[i])) * 0x7FFF;
    }

    const base64Data = encodePCM(new Uint8Array(int16.buffer));

    sessionPromise.then(session => {
        session.sendRealtimeInput({
            media: {
                mimeType: 'audio/pcm;rate=16000',
                data: base64Data
            }
        });
    });
  };

  const close = () => {
    sessionPromise.then(s => s.close());
  };

  return { sendAudio, close };
};

