import React, { useState, useEffect, useRef } from 'react';
import { chatFast, chatThinking, chatWithSearch } from '../services/geminiService';
import { ChatMessage } from '../types';

const Chat: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: "Systems online. Connected to KNON network. Select mode: FAST, DEEP, or WEB SEARCH. How may I assist?" }
  ]);
  const [input, setInput] = useState('');
  const [mode, setMode] = useState<'FAST' | 'DEEP' | 'SEARCH'>('FAST');
  const [loading, setLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(scrollToBottom, [messages]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMsg: ChatMessage = { role: 'user', text: input };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setLoading(true);

    try {
      let responseText = '';
      let sources = undefined;

      if (mode === 'DEEP') {
          responseText = await chatThinking(input);
      } else if (mode === 'SEARCH') {
          const res = await chatWithSearch(input);
          responseText = res.text;
          sources = res.sources;
      } else {
          responseText = await chatFast(input);
