import { AspectRatio, ImageSize, LabMode, VideoResolution, VideoAspectRatio, VideoModel } from '../types';

const EditLab: React.FC = () => {
  const [mode, setMode] = useState<LabMode>('GENERATE');
  const [prompt, setPrompt] = useState('');
  const [loading, setLoading] = useState(false);
  const [resultMedia, setResultMedia] = useState<string | null>(null);
  const [hasApiKey, setHasApiKey] = useState(true); // Optimistic default

  // Gen specific
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>(AspectRatio.SQUARE);
  const [imageSize, setImageSize] = useState<ImageSize>(ImageSize.SIZE_1K);

  // Edit specific
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Video specific
  const [videoResolution, setVideoResolution] = useState<VideoResolution>('720p');
  const [videoAspectRatio, setVideoAspectRatio] = useState<VideoAspectRatio>('16:9');
  const [videoModel, setVideoModel] = useState<VideoModel>('veo-3.1-fast-generate-preview');

  useEffect(() => {
    checkApiKey();
  }, [mode]);

  const checkApiKey = async () => {
     if (mode === 'GENERATE' || mode === 'VIDEO') { // Both Pro Image and Veo need paid key
         if ((window as any).aistudio) {
             const hasKey = await (window as any).aistudio.hasSelectedApiKey();
             setHasApiKey(hasKey);
         }
     }
  };

  const requestApiKey = async () => {
      if ((window as any).aistudio) {
          await (window as any).aistudio.openSelectKey();
          await checkApiKey();
      }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleExecute = async () => {
    if (!prompt) return;
    setLoading(true);
    setResultMedia(null);

    // Double check key before call
    if ((mode === 'GENERATE' || mode === 'VIDEO') && (window as any).aistudio) {
        const hasKey = await (window as any).aistudio.hasSelectedApiKey();
        if (!hasKey) {
            await requestApiKey();
            setLoading(false);
            return;
        }
    }

    try {
      if (mode === 'GENERATE') {
        const result = await generateImage(prompt, aspectRatio, imageSize);
        setResultMedia(result);
      } else if (mode === 'EDIT') {
        if (!selectedImage) return;
        const result = await editImage(selectedImage, prompt);
        setResultMedia(result);
      } else if (mode === 'VIDEO') {
        const result = await generateVideo(prompt, videoResolution, videoAspectRatio, videoModel);
        setResultMedia(result);
      }
    } catch (e) {
      console.error(e);
      // If error suggests auth, reset key state
      if (String(e).includes("Requested entity was not found")) {
         setHasApiKey(false);
      }
      alert("Operation failed. Check console.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen pt-20 pb-32 px-6 flex flex-col items-center max-w-7xl mx-auto">
      <div className="w-full mb-10 border-b border-white/10 pb-6 flex justify-between items-end">
        <div>
           <h1 className="text-5xl font-black uppercase mb-2">Visual Lab</h1>
           <p className="text-white/50 font-mono text-sm">
             {mode === 'VIDEO' ? 'Veo 3.1 Neural Video' : 'Gemini 3.0 Pro Image & 2.5 Flash'}
           </p>
        </div>
        <div className="flex gap-2">
            <button onClick={() => setMode('GENERATE')} className={`px-4 py-2 rounded border transition-all text-sm font-bold tracking-wide ${mode === 'GENERATE' ? 'bg-primary text-black border-primary' : 'border-white/20 text-white/60 hover:text-white'}`}>GENERATE</button>
            <button onClick={() => setMode('EDIT')} className={`px-4 py-2 rounded border transition-all text-sm font-bold tracking-wide ${mode === 'EDIT' ? 'bg-secondary text-black border-secondary' : 'border-white/20 text-white/60 hover:text-white'}`}>EDIT</button>
            <button onClick={() => setMode('VIDEO')} className={`px-4 py-2 rounded border transition-all text-sm font-bold tracking-wide ${mode === 'VIDEO' ? 'bg-white text-black border-white' : 'border-white/20 text-white/60 hover:text-white'}`}>VEO VIDEO</button>
        </div>
      </div>

      {(!hasApiKey && (mode === 'GENERATE' || mode === 'VIDEO')) && (
          <div className="w-full mb-8 bg-red-500/10 border border-red-500/50 p-4 rounded flex items-center justify-between">
              <div className="flex items-center gap-3">
                  <span className="material-symbols-outlined text-red-500">lock</span>
                  <p className="text-sm font-mono text-red-200">Billing Access Required for Pro/Veo Models</p>
              </div>
              <button onClick={requestApiKey} className="px-4 py-2 bg-red-500 text-white font-bold rounded hover:bg-red-400 transition-colors text-xs uppercase">
                  Select API Key
              </button>
          </div>
      )}

      <div className="flex flex-col lg:flex-row gap-12 w-full">
        {/* Controls */}
        <div className="w-full lg:w-1/3 flex flex-col gap-8">

            {mode === 'GENERATE' && (
                <div className="space-y-6 animate-pulse-slow bg-surface p-6 rounded border border-white/5">
                    <div>
                        <label className="block text-xs font-bold text-primary mb-2 tracking-widest">ASPECT RATIO</label>
                        <div className="grid grid-cols-4 gap-2">
                            {Object.values(AspectRatio).map((ratio) => (
                                <button key={ratio} onClick={() => setAspectRatio(ratio)} className={`text-xs py-2 border rounded transition-colors ${aspectRatio === ratio ? 'border-primary text-primary bg-primary/10' : 'border-white/10 text-white/40 hover:border-white/30'}`}>{ratio}</button>
                            ))}
                        </div>
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-primary mb-2 tracking-widest">RESOLUTION</label>
                        <div className="grid grid-cols-3 gap-2">
                            {Object.values(ImageSize).map((size) => (
                                <button key={size} onClick={() => setImageSize(size)} className={`text-xs py-2 border rounded transition-colors ${imageSize === size ? 'border-primary text-primary bg-primary/10' : 'border-white/10 text-white/40 hover:border-white/30'}`}>{size}</button>
                            ))}
                        </div>
                    </div>
                </div>
            )}

            {mode === 'EDIT' && (
                <div className="space-y-6 bg-surface p-6 rounded border border-white/5">
                    <label className="block text-xs font-bold text-secondary mb-2 tracking-widest">SOURCE IMAGE</label>
                    <div onClick={() => fileInputRef.current?.click()} className="w-full aspect-video border-2 border-dashed border-white/20 rounded hover:border-secondary hover:bg-secondary/5 cursor-pointer flex items-center justify-center relative overflow-hidden transition-all">
                        {selectedImage ? (
                            <img src={selectedImage} alt="Source" className="w-full h-full object-contain" />
                        ) : (
                            <div className="text-center text-white/40"><span className="material-symbols-outlined text-4xl mb-2">upload_file</span><p className="text-xs">CLICK TO UPLOAD</p></div>
                        )}
                    </div>
                    <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
                </div>
            )}

             {mode === 'VIDEO' && (
                <div className="space-y-6 bg-surface p-6 rounded border border-white/5">
                    <div className="flex items-start gap-3 mb-2">
                         <span className="material-symbols-outlined text-white/60">videocam</span>
                         <p className="text-xs text-white/40 leading-relaxed">
                            Veo 3.1 creates cinematic video content.
                         </p>
                    </div>

                    {/* Model Selection */}
                    <div>
                        <label className="block text-xs font-bold text-white/70 mb-2 tracking-widest">MODEL TIER</label>
                        <div className="grid grid-cols-2 gap-2">
                             <button onClick={() => setVideoModel('veo-3.1-fast-generate-preview')} className={`text-[10px] py-2 border rounded transition-colors ${videoModel === 'veo-3.1-fast-generate-preview' ? 'border-white text-white bg-white/10' : 'border-white/10 text-white/40 hover:border-white/30'}`}>FAST (TURBO)</button>
                             <button onClick={() => setVideoModel('veo-3.1-generate-preview')} className={`text-[10px] py-2 border rounded transition-colors ${videoModel === 'veo-3.1-generate-preview' ? 'border-white text-white bg-white/10' : 'border-white/10 text-white/40 hover:border-white/30'}`}>HIGH QUALITY</button>
                        </div>
                    </div>

                    {/* Format & Resolution */}
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-xs font-bold text-white/70 mb-2 tracking-widest">FORMAT</label>
                            <div className="flex gap-2">
                                <button onClick={() => setVideoAspectRatio('16:9')} className={`flex-1 text-[10px] py-2 border rounded transition-colors ${videoAspectRatio === '16:9' ? 'border-white text-white bg-white/10' : 'border-white/10 text-white/40 hover:border-white/30'}`}>16:9</button>
                                <button onClick={() => setVideoAspectRatio('9:16')} className={`flex-1 text-[10px] py-2 border rounded transition-colors ${videoAspectRatio === '9:16' ? 'border-white text-white bg-white/10' : 'border-white/10 text-white/40 hover:border-white/30'}`}>9:16</button>
                            </div>
                        </div>
                         <div>
                            <label className="block text-xs font-bold text-white/70 mb-2 tracking-widest">RESOLUTION</label>
                            <div className="flex gap-2">
                                <button onClick={() => setVideoResolution('720p')} className={`flex-1 text-[10px] py-2 border rounded transition-colors ${videoResolution === '720p' ? 'border-white text-white bg-white/10' : 'border-white/10 text-white/40 hover:border-white/30'}`}>720p</button>
                                <button onClick={() => setVideoResolution('1080p')} className={`flex-1 text-[10px] py-2 border rounded transition-colors ${videoResolution === '1080p' ? 'border-white text-white bg-white/10' : 'border-white/10 text-white/40 hover:border-white/30'}`}>1080p</button>
                            </div>
                        </div>
                    </div>

                    {/* Style Presets */}
                    <div>
                         <label className="block text-xs font-bold text-white/70 mb-2 tracking-widest">STYLE INJECTION</label>
                         <div className="flex flex-wrap gap-2">
                            {['Cyberpunk', 'VHS Glitch', 'Cinematic Noir', 'Photorealistic', 'Anime'].map(style => (
                                <button key={style} onClick={() => setPrompt(prev => prev + (prev ? ' ' : '') + style)} className="text-[10px] px-2 py-1 border border-white/20 rounded hover:bg-white/10 hover:border-white/50 transition-colors text-white/60 hover:text-white">
                                    + {style}
                                </button>
                            ))}
                         </div>
                    </div>
                </div>
            )}

            <div className="space-y-2">
                <label className="block text-xs font-bold text-white/70 tracking-widest">PROMPT INSTRUCTION</label>
                <textarea 
                    value={prompt}
                    onChange={(e) => setPrompt(e.target.value)}
                    placeholder={mode === 'VIDEO' ? "Describe the video (e.g., A neon hologram of a cat driving at top speed)..." : "Describe the visual..."}
                    className="w-full h-32 bg-background-dark border border-white/20 rounded p-4 text-white placeholder-white/20 focus:border-primary focus:ring-1 focus:ring-primary outline-none resize-none font-mono text-sm"
                />
            </div>

            <button 
                onClick={handleExecute}
                disabled={loading || !prompt || (mode === 'EDIT' && !selectedImage) || ((mode === 'GENERATE' || mode === 'VIDEO') && !hasApiKey)}
                className={`w-full py-4 font-bold uppercase tracking-widest rounded transition-all flex items-center justify-center gap-2 ${loading ? 'bg-white/10 cursor-not-allowed text-white/50' : mode === 'VIDEO' ? 'bg-white hover:bg-gray-200 text-black' : mode === 'GENERATE' ? 'bg-primary hover:bg-white text-black' : 'bg-secondary hover:bg-white text-black'}`}
            >
                {loading ? (
                    <>
                        <span className="w-4 h-4 border-2 border-black/50 border-t-transparent rounded-full animate-spin"></span>
                        PROCESSING
                    </>
                ) : (
                    <>
                        <span className="material-symbols-outlined">auto_awesome</span>
                        EXECUTE
                    </>
                )}
            </button>
        </div>

        {/* Result */}
        <div className="flex-1 bg-surface rounded-lg border border-white/10 p-2 flex items-center justify-center min-h-[500px] relative overflow-hidden">
             {/* CRT Overlay inside result box */}
             <div className="absolute inset-0 pointer-events-none opacity-20 bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.25)_50%),linear-gradient(90deg,rgba(255,0,0,0.06),rgba(0,255,0,0.02),rgba(0,0,255,0.06))] bg-[length:100%_4px,3px_100%]"></div>

             {resultMedia ? (
                 mode === 'VIDEO' ? (
                     <video src={resultMedia} controls autoPlay loop className="max-w-full max-h-full rounded shadow-2xl shadow-white/10" />
                 ) : (
                     <img src={resultMedia} alt="Result" className="max-w-full max-h-full object-contain rounded shadow-2xl shadow-primary/20" />
                 )
             ) : (
                 <div className="text-white/20 flex flex-col items-center">
                     <span className="material-symbols-outlined text-6xl mb-4">{mode === 'VIDEO' ? 'movie' : 'image'}</span>
                     <p className="font-mono text-sm tracking-widest">{loading ? 'RENDERING ON NEURAL GRID...' : 'AWAITING OUTPUT SIGNAL'}</p>
                 </div>
             )}
        </div>
      </div>
    </div>
  );
};

export default EditLab;
